archive_policies.description:
List of archive policies to predefine. Each item defines a policy name, aggregation methods, and definition (granularity + points).',
      "items": {
        "type": "object",
        "fields": {
          "name": {
            "type": "string",
            "default": "",
            "description": "Archive policy name (must be unique)."
          },
          "back_window": {
            "type": "number",
            "default": 0,
            "description": "Number of past granularities retained beyond current time window."
          },
          "definition": {
            "type": "list",
            "default": [],
            "description": "List of archive policy definitions, each in format 'granularity:points' (e.g., ['60s:86400', '3600s:87600']).",
            "items": {
              "type": "string"
            }
          },
          "aggregation_methods": {
            "type": "list",
            "default": [
              "mean"
            ],
            "description": "Supported aggregation methods for metrics in this policy.",
            "items": {
              "type": "string",
              "enum": [
                "mean",
                "min",
                "max",
                "sum",
                "std",
                "count"
              ]
            }
          }
        }
      }
    }
